const aiOutput = $input.first().json.output || $input.first().json.text || '';
const w = $('Today').first().json;

return [{
  json: {
    aiText: aiOutput,
    type: 'today',
    weatherData: {
      city: w.name || '',
      country: (w.sys && w.sys.country) || '',
      temp: w.main && w.main.temp,
      feelsLike: w.main && w.main.feels_like,
      tempMin: w.main && w.main.temp_min,
      tempMax: w.main && w.main.temp_max,
      humidity: w.main && w.main.humidity,
      pressure: w.main && w.main.pressure,
      visibility: w.visibility,
      windSpeed: w.wind && w.wind.speed,
      windDeg: w.wind && w.wind.deg,
      description: (w.weather && w.weather[0] && w.weather[0].description) || '',
      icon: (w.weather && w.weather[0] && w.weather[0].icon) || '01d',
      timestamp: w.dt,
      sunrise: w.sys && w.sys.sunrise,
      sunset: w.sys && w.sys.sunset
    }
  }
}];

const aiOutput = $input.first().json.output || $input.first().json.text || '';
const f = $('OpenWeatherMap').first().json;
const list = f.list || [];
const city = f.city || {};
const cur = list[0] || {};

const weatherData = {
  city: city.name || '',
  country: city.country || '',
  temp: cur.main && cur.main.temp,
  feelsLike: cur.main && cur.main.feels_like,
  tempMin: cur.main && cur.main.temp_min,
  tempMax: cur.main && cur.main.temp_max,
  humidity: cur.main && cur.main.humidity,
  pressure: cur.main && cur.main.pressure,
  visibility: cur.visibility || 10000,
  windSpeed: cur.wind && cur.wind.speed,
  windDeg: cur.wind && cur.wind.deg,
  description: (cur.weather && cur.weather[0] && cur.weather[0].description) || '',
  icon: (cur.weather && cur.weather[0] && cur.weather[0].icon) || '01d',
  timestamp: cur.dt,
  sunrise: city.sunrise,
  sunset: city.sunset
};

const daily = [];
for (let i = 0; i < list.length && daily.length < 5; i += 8) {
  const item = list[i];
  if (item) {
    daily.push({
      dt: item.dt,
      temp: item.main && item.main.temp,
      minTemp: item.main && item.main.temp_min,
      maxTemp: item.main && item.main.temp_max,
      description: (item.weather && item.weather[0] && item.weather[0].description) || '',
      icon: (item.weather && item.weather[0] && item.weather[0].icon) || '01d',
      humidity: item.main && item.main.humidity,
      rainProb: item.pop ? Math.round(item.pop * 100) : 0
    });
  }
}

const hourly = list.slice(0, 8).map(item => ({
  dt: item.dt,
  temp: item.main && item.main.temp,
  description: (item.weather && item.weather[0] && item.weather[0].description) || '',
  icon: (item.weather && item.weather[0] && item.weather[0].icon) || '01d',
  humidity: item.main && item.main.humidity,
  rainProb: item.pop ? Math.round(item.pop * 100) : 0
}));

return [{
  json: {
    aiText: aiOutput,
    type: '5day',
    weatherData: weatherData,
    daily: daily,
    hourly: hourly
  }
}];
